## 3. Service Class

```x++
/// <summary>
/// Custom REST service for customer operations
/// </summary>
public class CustomerRESTService
{
    /// <summary>
    /// Get customer information by customer account
    /// </summary>
    [AifCollectionType('return', Types::Class, classStr(CustomerDataContract))]
    public CustomerDataContract getCustomer(CustAccount _custAccount)
    {
        CustomerDataContract    customerData = new CustomerDataContract();
        CustTable              custTable;
        DirPartyTable          dirPartyTable;
        LogisticsPostalAddress postalAddress;

        try
        {
            if (_custAccount)
            {
                custTable = CustTable::find(_custAccount);

                if (custTable)
                {
                    dirPartyTable = DirPartyTable::findRec(custTable.Party);

                    // Get primary address
                    postalAddress = DirParty::primaryPostalAddress(custTable.Party);

                    // Populate contract
                    customerData.parmCustAccount(custTable.AccountNum);
                    customerData.parmCustName(dirPartyTable.Name);
                    customerData.parmCustGroup(custTable.CustGroup);
                    customerData.parmEmail(this.getCustomerEmail(custTable.Party));
                    customerData.parmPhone(this.getCustomerPhone(custTable.Party));

                    if (postalAddress)
                    {
                        customerData.parmAddress(postalAddress.Address);
                    }
                }
            }
        }
        catch (Exception::Error)
        {
            throw error("Error retrieving customer information");
        }

        return customerData;
    }

    /// <summary>
    /// Get list of all customers
    /// </summary>
    [AifCollectionType('return', Types::Class, classStr(CustomerDataContract))]
    public List getCustomerList()
    {
        List                   customerList = new List(Types::Class);
        CustTable             custTable;
        CustomerDataContract  customerData;
        DirPartyTable         dirPartyTable;

        while select custTable
            where custTable.AccountNum != ''
        {
            dirPartyTable = DirPartyTable::findRec(custTable.Party);

            customerData = new CustomerDataContract();
            customerData.parmCustAccount(custTable.AccountNum);
            customerData.parmCustName(dirPartyTable.Name);
            customerData.parmCustGroup(custTable.CustGroup);
            customerData.parmEmail(this.getCustomerEmail(custTable.Party));
            customerData.parmPhone(this.getCustomerPhone(custTable.Party));

            customerList.addEnd(customerData);
        }

        return customerList;
    }

    /// <summary>
    /// Create a new customer
    /// </summary>
    public CustomerResponseContract createCustomer(CustomerDataContract _customerData)
    {
        CustomerResponseContract response = new CustomerResponseContract();
        CustTable                custTable;
        DirParty                 dirParty;
        DirPartyTable           dirPartyTable;

        try
        {
            ttsbegin;

            // Validate input
            if (!_customerData.parmCustAccount())
            {
                response.parmSuccess(false);
                response.parmMessage("Customer account is required");
                return response;
            }

            // Check if customer already exists
            if (CustTable::exist(_customerData.parmCustAccount()))
            {
                response.parmSuccess(false);
                response.parmMessage(strFmt("Customer %1 already exists", _customerData.parmCustAccount()));
                return response;
            }

            // Create party
            dirPartyTable.clear();
            dirPartyTable.Name = _customerData.parmCustName();
            dirPartyTable.insert();

            // Create customer
            custTable.clear();
            custTable.initValue();
            custTable.AccountNum = _customerData.parmCustAccount();
            custTable.Party = dirPartyTable.RecId;
            custTable.CustGroup = _customerData.parmCustGroup() ? _customerData.parmCustGroup() : 'DEFAULT';
            custTable.insert();

            // Add email if provided
            if (_customerData.parmEmail())
            {
                this.createCustomerEmail(custTable.Party, _customerData.parmEmail());
            }

            // Add phone if provided
            if (_customerData.parmPhone())
            {
                this.createCustomerPhone(custTable.Party, _customerData.parmPhone());
            }

            ttscommit;

            response.parmSuccess(true);
            response.parmMessage("Customer created successfully");
            response.parmCustomerId(custTable.AccountNum);
        }
        catch (Exception::Error)
        {
            response.parmSuccess(false);
            response.parmMessage("Error creating customer");
        }

        return response;
    }

    /// <summary>
    /// Update existing customer
    /// </summary>
    public CustomerResponseContract updateCustomer(CustomerDataContract _customerData)
    {
        CustomerResponseContract response = new CustomerResponseContract();
        CustTable               custTable;
        DirPartyTable          dirPartyTable;

        try
        {
            ttsbegin;

            custTable = CustTable::find(_customerData.parmCustAccount(), true);

            if (!custTable)
            {
                response.parmSuccess(false);
                response.parmMessage(strFmt("Customer %1 not found", _customerData.parmCustAccount()));
                return response;
            }

            // Update party name
            if (_customerData.parmCustName())
            {
                dirPartyTable = DirPartyTable::findRec(custTable.Party, true);
                dirPartyTable.Name = _customerData.parmCustName();
                dirPartyTable.update();
            }

            // Update customer group
            if (_customerData.parmCustGroup())
            {
                custTable.CustGroup = _customerData.parmCustGroup();
                custTable.update();
            }

            ttscommit;

            response.parmSuccess(true);
            response.parmMessage("Customer updated successfully");
            response.parmCustomerId(custTable.AccountNum);
        }
        catch (Exception::Error)
        {
            response.parmSuccess(false);
            response.parmMessage("Error updating customer");
        }

        return response;
    }

    /// <summary>
    /// Delete a customer
    /// </summary>
    public CustomerResponseContract deleteCustomer(CustAccount _custAccount)
    {
        CustomerResponseContract response = new CustomerResponseContract();
        CustTable               custTable;

        try
        {
            ttsbegin;

            custTable = CustTable::find(_custAccount, true);

            if (!custTable)
            {
                response.parmSuccess(false);
                response.parmMessage(strFmt("Customer %1 not found", _custAccount));
                return response;
            }

            custTable.delete();

            ttscommit;

            response.parmSuccess(true);
            response.parmMessage("Customer deleted successfully");
            response.parmCustomerId(_custAccount);
        }
        catch (Exception::Error)
        {
            response.parmSuccess(false);
            response.parmMessage("Error deleting customer. Customer might have related transactions.");
        }

        return response;
    }

    // Helper methods
    private str getCustomerEmail(RefRecId _party)
    {
        LogisticsElectronicAddress electronicAddress;

        select firstonly electronicAddress
            where electronicAddress.Party == _party
               && electronicAddress.Type == LogisticsElectronicAddressMethodType::Email
               && electronicAddress.IsPrimary == true;

        return electronicAddress.Locator;
    }

    private str getCustomerPhone(RefRecId _party)
    {
        LogisticsElectronicAddress electronicAddress;

        select firstonly electronicAddress
            where electronicAddress.Party == _party
               && electronicAddress.Type == LogisticsElectronicAddressMethodType::Phone
               && electronicAddress.IsPrimary == true;

        return electronicAddress.Locator;
    }

    private void createCustomerEmail(RefRecId _party, str _email)
    {
        LogisticsElectronicAddress electronicAddress;

        electronicAddress.clear();
        electronicAddress.Party = _party;
        electronicAddress.Type = LogisticsElectronicAddressMethodType::Email;
        electronicAddress.Locator = _email;
        electronicAddress.IsPrimary = true;
        electronicAddress.insert();
    }

    private void createCustomerPhone(RefRecId _party, str _phone)
    {
        LogisticsElectronicAddress electronicAddress;

        electronicAddress.clear();
        electronicAddress.Party = _party;
        electronicAddress.Type = LogisticsElectronicAddressMethodType::Phone;
        electronicAddress.Locator = _phone;
        electronicAddress.IsPrimary = true;
        electronicAddress.insert();
    }
}
```

## 4. Service Group Creation

After creating the classes, you need to:

1. **Create a Service**:
   - In AOT, right-click on **Services** and create a new service
   - Name it `CustomerRESTService`
   - Set the Class property to `CustomerRESTService`
   - Add service operations for each method you want to expose

2. **Create a Service Group**:
   - Right-click on **Service Groups** and create new
   - Name it `CustomerServiceGroup`
   - Add your service to this group

3. **Deploy the Service**:
   - Right-click on the service group
   - Select **Deploy Service Group**

## 5. Testing the Service

The REST endpoints will be available at:
```
https://[your-aos-url]/api/services/CustomerServiceGroup/CustomerRESTService/[MethodName]
```

Example endpoints:
- GET: `/api/services/CustomerServiceGroup/CustomerRESTService/getCustomer?_custAccount=CUST001`
- GET: `/api/services/CustomerServiceGroup/CustomerRESTService/getCustomerList`
- POST: `/api/services/CustomerServiceGroup/CustomerRESTService/createCustomer`
- POST: `/api/services/CustomerServiceGroup/CustomerRESTService/updateCustomer`
- DELETE: `/api/services/CustomerServiceGroup/CustomerRESTService/deleteCustomer?_custAccount=CUST001`

## 6. Authentication

For authentication, you'll need to:
1. Register your application in Azure AD
2. Use OAuth 2.0 bearer tokens
3. Include the token in the Authorization header

This complete example provides a fully functional REST service for customer operations in Dynamics AX/D365FO with CRUD operations and proper error handling.

